function initReveal(){if(!("IntersectionObserver"in window)||window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;const s=[[".hero__content > *",85],[".about__intro, .about .feature",85],[".services .section-heading, .service-card",55],[".reasons .section-title, .reason",75],[".team .section-heading, .master-card",70],[".prices .section-heading, .prices__lists, .prices__gift",90],[".reviews .section-heading, .review",75],[".works .section-heading, .works__gallery",90],[".booking-banner__container > div, .booking-banner__container > button",100],[".legal-content__container > *",80]],n=[];for(const[e,t]of s)document.querySelectorAll(e).forEach((r,i)=>{r.dataset.reveal="",r.style.setProperty("--reveal-delay",`${Math.min(i*t,280)}ms`),n.push(r)});if(!n.length)return;document.documentElement.classList.add("motion-ready");const o=new IntersectionObserver(e=>{for(const t of e)t.isIntersecting&&(t.target.classList.add("is-visible"),o.unobserve(t.target))},{threshold:.08,rootMargin:"0px 0px -5% 0px"});n.forEach(e=>o.observe(e))}initReveal();
